package com.yeyamo_mobile.api.recommendation_service.domain;import java.util.*;
public record RecommendationProfile(String userId,String preferredRegion,String countryCode,Set<String>contentCountries,Set<String>contentLanguages,boolean locationSharingEnabled,Map<String,Double>categoryAffinity,Set<String>seenSources){public RecommendationProfile{contentCountries=contentCountries==null?Set.of():Set.copyOf(contentCountries);contentLanguages=contentLanguages==null?Set.of():Set.copyOf(contentLanguages);categoryAffinity=categoryAffinity==null?Map.of():Map.copyOf(categoryAffinity);seenSources=seenSources==null?Set.of():Set.copyOf(seenSources);}public RecommendationProfile(String userId,String preferredRegion,boolean locationSharingEnabled,Map<String,Double>categoryAffinity,Set<String>seenSources){this(userId,preferredRegion,null,Set.of(),Set.of(),locationSharingEnabled,categoryAffinity,seenSources);}}
